  --radius:       10px;
  --radius-sm:    6px;
  --transition:   180ms ease;
}

/* ── Skip link ── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: 0.5rem 1rem;
  background: var(--accent);
  color: #fff;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  z-index: 100;
  transition: top var(--transition);
}
.skip-link:focus {
  top: 1rem;
  outline: 3px solid var(--border-focus);
  outline-offset: 2px;
}

