body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  min-height: 100vh;
  padding: 2rem 1rem 4rem;
}

main {
  max-width: 680px;
  margin: 0 auto;
}

/* ── Quiz header ── */
.quiz-header {
  margin-bottom: 2.5rem;
  text-align: center;
}

h1 {
  font-size: clamp(1.6rem, 4vw, 2.2rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  background: linear-gradient(135deg, #a5b4fc, #818cf8);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  margin-bottom: 0.5rem;
}

.quiz-intro {
  color: var(--text-muted);
  font-size: 0.95rem;
}

/* ── Form field cards ── */
.form-field {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.75rem;
  margin-bottom: 1.25rem;
  transition: border-color var(--transition);
}

.form-field:focus-within {
  border-color: var(--border-focus);
}

/* ── Fieldset / legend ── */
fieldset {
  border: none;
  padding: 0;
}

legend {
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--text);
  margin-bottom: 0.75rem;
  line-height: 1.5;
}

legend em {
  font-style: normal;
  color: var(--accent-hover);
}

/* ── Help & error text ── */
.help-text {
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-bottom: 1.1rem;
  padding: 0.6rem 0.85rem;
  background: var(--surface-2);
  border-left: 3px solid var(--accent);
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
}

.error-text {
  font-size: 0.875rem;
  color: var(--error);
  margin-top: 0.75rem;
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

.error-text::before {
  content: "⚠";
  flex-shrink: 0;
}

.error-text[hidden] {
  display: none;
}

/* ── Options list ── */
.options {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

/* ── Custom checkbox labels ── */
.option {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.65rem 1rem;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  background: var(--surface-2);
  cursor: pointer;
  transition:
    background var(--transition),
    border-color var(--transition);
  font-size: 0.95rem;
  user-select: none;
  position: relative;
}

.option:hover {
  background: #252944;
  border-color: var(--accent);
}

/* Hide native checkbox visually but keep it accessible */
.option input[type="checkbox"] {
  position: absolute;
  opacity: 0;
  width: 1.25rem;
  height: 1.25rem;
  margin: 0;
  cursor: pointer;
  /* Keep it overlapping the custom box so click/touch targets align */
  left: 1rem;
  top: 50%;
  transform: translateY(-50%);
  z-index: 1;
}

/* Custom visual checkbox */
.checkbox-custom {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.25rem;
  height: 1.25rem;
  flex-shrink: 0;
  border: 2px solid var(--border-focus);
  border-radius: 4px;
  background: transparent;
  transition:
    background var(--transition),
    border-color var(--transition);
  pointer-events: none;
}

/* Checked state */
.option input[type="checkbox"]:checked + .checkbox-custom {
  background: var(--accent);
  border-color: var(--accent);
}

.option input[type="checkbox"]:checked + .checkbox-custom::after {
  content: "";
  display: block;
  width: 0.35rem;
  height: 0.6rem;
  border: 2px solid #fff;
  border-top: none;
  border-left: none;
  transform: rotate(45deg) translateY(-1px);
}

/* Focus indicator — visible ring on the label */
.option input[type="checkbox"]:focus-visible + .checkbox-custom {
  outline: 3px solid var(--border-focus);
  outline-offset: 2px;
  border-radius: 4px;
}

/* Selected label highlight */
.option:has(input[type="checkbox"]:checked) {
  background: #1f2340;
  border-color: var(--accent);
  color: var(--accent-hover);
}

/* Invalid group — highlight the card */
.form-field.invalid fieldset {
  /* error shown via error-text element */
}

.form-field.invalid {
  border-color: var(--error);
}

/* ── Required marker & note ── */
.required-marker {
  color: var(--error);
  margin-left: 0.2rem;
}

.required-note {
  font-size: 0.8rem;
  color: var(--text-muted);
  margin-bottom: 1.5rem;
}

/* ── Submit button ── */
.submit-btn {
  display: block;
  width: 100%;
  padding: 0.85rem 1.5rem;
  background: var(--accent);
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition:
    background var(--transition),
    transform 80ms ease;
  letter-spacing: 0.02em;
}

.submit-btn:hover {
  background: var(--accent-hover);
}

.submit-btn:focus-visible {
  outline: 3px solid var(--border-focus);
  outline-offset: 3px;
}

.submit-btn:active {
  transform: scale(0.99);
}

/* ── Results panel ── */
.results {
  margin-top: 2rem;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 2rem;
  animation: fadeIn 300ms ease;
}

.results[hidden] {
  display: none;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
