+/* ── Form field cards ── */
+.form-field {
+  background: var(--surface);
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  padding: 1.75rem;
+  margin-bottom: 1.25rem;
+  transition: border-color var(--transition);
+}
+
+.form-field:focus-within {
+  border-color: var(--border-focus);
+}
+
+/* ── Fieldset / legend ── */
+fieldset {
+  border: none;
+  padding: 0;
+}
+
+legend {
+  font-size: 1.05rem;
+  font-weight: 600;
+  color: var(--text);
+  margin-bottom: 0.75rem;
+  line-height: 1.5;
+}
+
+legend em {
+  font-style: normal;
+  color: var(--accent-hover);
+}
+
+/* ── Help & error text ── */
+.help-text {
+  font-size: 0.875rem;
+  color: var(--text-muted);
+  margin-bottom: 1.1rem;
+  padding: 0.6rem 0.85rem;
+  background: var(--surface-2);
+  border-left: 3px solid var(--accent);
+  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
+}
+
+.error-text {
+  font-size: 0.875rem;
+  color: var(--error);
+  margin-top: 0.75rem;
+  display: flex;
+  align-items: center;
+  gap: 0.4rem;
+}
+
+.error-text::before {
+  content: "⚠";
+  flex-shrink: 0;
+}
+
+.error-text[hidden] {
+  display: none;
+}
+
+/* ── Options list ── */
+.options {
+  display: flex;
+  flex-direction: column;
+  gap: 0.6rem;
+}
+
+/* ── Custom checkbox labels ── */
+.option {
+  display: flex;
+  align-items: center;
+  gap: 0.75rem;
+  padding: 0.65rem 1rem;
+  border-radius: var(--radius-sm);
+  border: 1px solid var(--border);
+  background: var(--surface-2);
+  cursor: pointer;
+  transition:
+    background var(--transition),
+    border-color var(--transition);
+  font-size: 0.95rem;
+  user-select: none;
+  position: relative;
+}
+
+.option:hover {
+  background: #252944;
+  border-color: var(--accent);
+}
+
+/* Hide native checkbox visually but keep it accessible */
+.option input[type="checkbox"] {
+  position: absolute;
+  opacity: 0;
+  width: 1.25rem;
+  height: 1.25rem;
+  margin: 0;
+  cursor: pointer;
+  /* Keep it overlapping the custom box so click/touch targets align */
+  left: 1rem;
+  top: 50%;
+  transform: translateY(-50%);
+  z-index: 1;
+}
+
+/* Custom visual checkbox */
+.checkbox-custom {
+  display: inline-flex;
+  align-items: center;
+  justify-content: center;
+  width: 1.25rem;
+  height: 1.25rem;
+  flex-shrink: 0;
+  border: 2px solid var(--border-focus);
+  border-radius: 4px;
+  background: transparent;
+  transition:
+    background var(--transition),
+    border-color var(--transition);
+  pointer-events: none;
+}
+
+/* Checked state */
+.option input[type="checkbox"]:checked + .checkbox-custom {
+  background: var(--accent);
+  border-color: var(--accent);
+}
+
+.option input[type="checkbox"]:checked + .checkbox-custom::after {
+  content: "";
+  display: block;
+  width: 0.35rem;
+  height: 0.6rem;
+  border: 2px solid #fff;
+  border-top: none;
+  border-left: none;
+  transform: rotate(45deg) translateY(-1px);
+}
+
+/* Focus indicator — visible ring on the label */
+.option input[type="checkbox"]:focus-visible + .checkbox-custom {
+  outline: 3px solid var(--border-focus);
+  outline-offset: 2px;
+  border-radius: 4px;
+}
+
+/* Selected label highlight */
+.option:has(input[type="checkbox"]:checked) {
+  background: #1f2340;
+  border-color: var(--accent);
+  color: var(--accent-hover);
+}
+
+/* Invalid group — highlight the card */
+.form-field.invalid fieldset {
+  /* error shown via error-text element */
+}
+
+.form-field.invalid {
+  border-color: var(--error);
+}
+
+/* ── Required marker & note ── */
+.required-marker {
+  color: var(--error);
+  margin-left: 0.2rem;
+}
+
+.required-note {
+  font-size: 0.8rem;
+  color: var(--text-muted);
+  margin-bottom: 1.5rem;
+}
+
+/* ── Submit button ── */
+.submit-btn {
+  display: block;
+  width: 100%;
+  padding: 0.85rem 1.5rem;
+  background: var(--accent);
+  color: #fff;
+  font-size: 1rem;
+  font-weight: 600;
+  border: none;
+  border-radius: var(--radius-sm);
+  cursor: pointer;
+  transition:
+    background var(--transition),
+    transform 80ms ease;
+  letter-spacing: 0.02em;
+}
+
+.submit-btn:hover {
+  background: var(--accent-hover);
+}
+
+.submit-btn:focus-visible {
+  outline: 3px solid var(--border-focus);
+  outline-offset: 3px;
+}
+
+.submit-btn:active {
+  transform: scale(0.99);
+}
+
+/* ── Results panel ── */
+.results {
+  margin-top: 2rem;
+  background: var(--surface);
+  border: 1px solid var(--border);
+  border-radius: var(--radius);
+  padding: 2rem;
+  animation: fadeIn 300ms ease;
+}
+
+.results[hidden] {
+  display: none;
+}
+
+@keyframes fadeIn {
+  from { opacity: 0; transform: translateY(8px); }
+  to   { opacity: 1; transform: translateY(0); }
+}
+
+.results h2 {
+  font-size: 1.3rem;
+  font-weight: 700;
+  margin-bottom: 0.75rem;
+  color: var(--text);
+}
+
+.score-summary {
+  font-size: 1.1rem;
+  font-weight: 600;
+  color: var(--success);
+  margin-bottom: 1.25rem;
+}
+
+.results-list {
+  list-style: none;
+  display: flex;
+  flex-direction: column;
+  gap: 0.85rem;
+  margin-bottom: 1.75rem;
+}
+
+.results-list li {
+  padding: 0.85rem 1rem;
+  border-radius: var(--radius-sm);
+  background: var(--surface-2);
+  border-left: 4px solid transparent;
+  font-size: 0.95rem;
+  line-height: 1.5;
+}
+
+.results-list li.correct {
+  border-left-color: var(--success);
+}
+
+.results-list li.incorrect {
+  border-left-color: var(--error);
+}
+
+.result-label {
+  font-weight: 600;
+  display: block;
+  margin-bottom: 0.3rem;
+}
+
+.result-detail {
+  color: var(--text-muted);
+  font-size: 0.875rem;
+}
+
+.result-status {
+  font-size: 0.8rem;
+  font-weight: 700;
+  text-transform: uppercase;
+  letter-spacing: 0.06em;
+  margin-top: 0.3rem;
+  display: block;
+}
+
+.correct .result-status { color: var(--success); }
+.incorrect .result-status { color: var(--error); }
+
+/* ── Retry button ── */
+.retry-btn {
+  display: inline-flex;
+  align-items: center;
+  gap: 0.4rem;
+  padding: 0.65rem 1.25rem;
+  background: transparent;
+  color: var(--accent-hover);
+  border: 1px solid var(--accent);
+  border-radius: var(--radius-sm);
+  font-size: 0.95rem;
+  font-weight: 600;
+  cursor: pointer;
+  transition:
+    background var(--transition),
+    color var(--transition);
+}
+
+.retry-btn:hover {
+  background: var(--accent);
+  color: #fff;
+}
+
+.retry-btn:focus-visible {
+  outline: 3px solid var(--border-focus);
+  outline-offset: 3px;
+}
+
+/* ── Forced colors / high contrast ── */
+@media (forced-colors: active) {
+  .checkbox-custom {
+    border: 2px solid ButtonText;
+    background: Field;
+  }
+  .option input[type="checkbox"]:checked + .checkbox-custom {
+    background: Highlight;
+    border-color: Highlight;
+  }
+  .submit-btn, .retry-btn {
+    forced-color-adjust: none;
+    background: ButtonFace;
+    color: ButtonText;
+    border: 2px solid ButtonText;
+  }
+}
+
+/* ── Narrow viewport reflow ── */
+@media (max-width: 400px) {
+  .form-field {
+    padding: 1.25rem 1rem;
+  }
+  .option {
+    padding: 0.55rem 0.75rem;
+  }
+}
+
