  resultsList.innerHTML = '';
  let score = 0;

  QUESTIONS.forEach(({ name, text, correct }) => {
    const selected = Array.from(
      form.querySelectorAll(`[name="${name}"]:checked`)
    ).map((cb) => cb.value);

    const isCorrect =
      selected.length === correct.length &&
      correct.every((v) => selected.includes(v));

    if (isCorrect) score++;

    const li = document.createElement('li');
    li.className = isCorrect ? 'correct' : 'incorrect';

    const correctLabels = correct.map((v) => labelFor(name, v)).join(', ');
    const selectedLabels = selected.map((v) => labelFor(name, v)).join(', ');

    li.innerHTML = `
      <span class="result-label">${text}</span>
      <span class="result-detail">Your answer: ${selectedLabels || 'None'}</span>
      ${!isCorrect ? `<span class="result-detail">Correct answer: ${correctLabels}</span>` : ''}
      <span class="result-status">${isCorrect ? '✓ Correct' : '✗ Incorrect'}</span>
    `;
    resultsList.appendChild(li);
  });

  const total = QUESTIONS.length;
  scoreSummary.textContent = `You scored ${score} out of ${total} question${total !== 1 ? 's' : ''}.`;

  form.hidden = true;
  resultsSection.hidden = false;
  resultsSection.querySelector('h2').focus();
}

/** Resets the quiz back to initial state. */
function resetQuiz() {
  form.reset();

  QUESTIONS.forEach(({ name, errorId }) => {
    const field = form.querySelector(`[name="${name}"]`).closest('.form-field');
    field.classList.remove('invalid');
    document.getElementById(errorId).hidden = true;
  });

  resultsSection.hidden = true;
  form.hidden = false;
  form.querySelector('fieldset').querySelector('input').focus();
}

/** Returns the visible label text for a given checkbox value. */
function labelFor(name, value) {
  const input = form.querySelector(`[name="${name}"][value="${value}"]`);
  if (!input) return value;
  return input.closest('label').textContent.trim();
}
