*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

/* ── Design tokens ── */
:root {
  --bg:           #0d0f1a;
  --surface:      #151826;
  --surface-2:    #1e2235;
  --border:       #2a2f4a;
  --border-focus: #7c84f8;
  --text:         #e2e6f3;
  --text-muted:   #8b92b8;
  --accent:       #6366f1;
  --accent-hover: #818cf8;
  --success:      #34d399;
  --error:        #f87171;
  --radius:       10px;
  --radius-sm:    6px;
  --transition:   180ms ease;
}

/* ── Skip link ── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: 0.5rem 1rem;
  background: var(--accent);
  color: #fff;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  z-index: 100;
  transition: top var(--transition);
}
.skip-link:focus {
  top: 1rem;
  outline: 3px solid var(--border-focus);
  outline-offset: 2px;
}

/* ── Page layout ── */
body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  min-height: 100vh;
  padding: 2rem 1rem 4rem;
}

main {
  max-width: 680px;
  margin: 0 auto;
}

/* ── Quiz header ── */
.quiz-header {
  margin-bottom: 2.5rem;
  text-align: center;
}

h1 {
  font-size: clamp(1.6rem, 4vw, 2.2rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  background: linear-gradient(135deg, #a5b4fc, #818cf8);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  margin-bottom: 0.5rem;
}

.quiz-intro {
  color: var(--text-muted);
  font-size: 0.95rem;
}

/* ── Form field cards ── */
.form-field {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.75rem;
  margin-bottom: 1.25rem;
  transition: border-color var(--transition);
}

.form-field:focus-within {
  border-color: var(--border-focus);
}

/* ── Fieldset / legend ── */
fieldset {
  border: none;
  padding: 0;
}

legend {
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--text);
  margin-bottom: 0.75rem;
  line-height: 1.5;
}

legend em {
  font-style: normal;
  color: var(--accent-hover);
}

/* ── Help & error text ── */
.help-text {
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-bottom: 1.1rem;
  padding: 0.6rem 0.85rem;
  background: var(--surface-2);
  border-left: 3px solid var(--accent);
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
}

.error-text {
  font-size: 0.875rem;
  color: var(--error);
  margin-top: 0.75rem;
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

.error-text::before {
  content: "⚠";
  flex-shrink: 0;
}

.error-text[hidden] {
  display: none;
}

/* ── Options list ── */
.options {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

/* ── Custom checkbox labels ── */
.option {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.65rem 1rem;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  background: var(--surface-2);
  cursor: pointer;
  transition:
    background var(--transition),
    border-color var(--transition);
  font-size: 0.95rem;
  user-select: none;
  position: relative;
}

.option:hover {
  background: #252944;
  border-color: var(--accent);
}

/* Hide native checkbox visually but keep it accessible */
.option input[type="checkbox"] {
  position: absolute;
  opacity: 0;
  width: 1.25rem;
  height: 1.25rem;
  margin: 0;
  cursor: pointer;
  /* Keep it overlapping the custom box so click/touch targets align */
  left: 1rem;
  top: 50%;
  transform: translateY(-50%);
  z-index: 1;
}

/* Custom visual checkbox */
.checkbox-custom {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 1.25rem;
  height: 1.25rem;
  flex-shrink: 0;
  border: 2px solid var(--border-focus);
  border-radius: 4px;
